namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string InstructorName { get; set; }
    public required string InstructorBio { get; set; }
    public required string DepartmentCode { get; set; }
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public required string Code { get; set; }
    public required string Name { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    public string? FullName { get; set; }

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]+$", ErrorMessage = "Student ID must be alphanumeric.")]
    public string? StudentId { get; set; }

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    IReadOnlyList<Course> GetCourses(string? searchTerm = null, string? departmentCode = null);
    IReadOnlyList<Course> GetFeaturedCourses();
    Course? GetCourseById(int id);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Code = "CS", Name = "Computer Science" },
        new() { Code = "MATH", Name = "Mathematics" },
        new() { Code = "ENG", Name = "English" },
        new() { Code = "PHYS", Name = "Physics" },
        new() { Code = "HIST", Name = "History" },
    ];

    private static readonly List<Course> Courses =
    [
        new()
        {
            Id = 1, Code = "CS 101", Title = "Introduction to Computer Science",
            Description = "A broad introduction to computer science covering algorithms, data structures, and programming fundamentals using Python.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM",
            InstructorName = "Dr. Sarah Chen",
            InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has 15 years of experience teaching introductory courses. Her research focuses on CS education and adaptive learning systems.",
            DepartmentCode = "CS", IsFeatured = true
        },
        new()
        {
            Id = 2, Code = "CS 301", Title = "Data Structures and Algorithms",
            Description = "Advanced study of data structures including trees, graphs, and hash tables, along with algorithm design and analysis techniques.",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM",
            InstructorName = "Prof. Michael Torres",
            InstructorBio = "Prof. Torres is an ACM Distinguished Educator with publications in algorithmic complexity and competitive programming pedagogy.",
            DepartmentCode = "CS", IsFeatured = true
        },
        new()
        {
            Id = 3, Code = "CS 420", Title = "Machine Learning",
            Description = "Foundations of machine learning including supervised and unsupervised learning, neural networks, and model evaluation.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM",
            InstructorName = "Dr. Aisha Patel",
            InstructorBio = "Dr. Patel's research spans deep learning and natural language processing. She previously worked at Google Brain before joining the faculty.",
            DepartmentCode = "CS", IsFeatured = false
        },
        new()
        {
            Id = 4, Code = "MATH 201", Title = "Linear Algebra",
            Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to science and engineering.",
            Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM",
            InstructorName = "Dr. James Whitfield",
            InstructorBio = "Dr. Whitfield is an award-winning mathematics educator specializing in applied linear algebra and numerical methods.",
            DepartmentCode = "MATH", IsFeatured = true
        },
        new()
        {
            Id = 5, Code = "MATH 301", Title = "Probability and Statistics",
            Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, and regression analysis.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM",
            InstructorName = "Prof. Lisa Nakamura",
            InstructorBio = "Prof. Nakamura has 20 years of teaching experience and has authored two widely-used textbooks on statistics for the sciences.",
            DepartmentCode = "MATH", IsFeatured = false
        },
        new()
        {
            Id = 6, Code = "ENG 110", Title = "Academic Writing",
            Description = "Development of college-level writing skills with emphasis on argumentation, research, and critical analysis of texts.",
            Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM",
            InstructorName = "Prof. David Okonkwo",
            InstructorBio = "Prof. Okonkwo is a published author and writing workshop leader with expertise in rhetoric and composition studies.",
            DepartmentCode = "ENG", IsFeatured = false
        },
        new()
        {
            Id = 7, Code = "ENG 250", Title = "World Literature",
            Description = "Survey of major literary works from diverse cultural traditions, exploring themes of identity, power, and human experience.",
            Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM",
            InstructorName = "Dr. Maria Gonzalez",
            InstructorBio = "Dr. Gonzalez specializes in comparative literature and postcolonial studies. She has published extensively on Latin American fiction.",
            DepartmentCode = "ENG", IsFeatured = true
        },
        new()
        {
            Id = 8, Code = "PHYS 101", Title = "General Physics I",
            Description = "Introductory physics covering mechanics, thermodynamics, and waves with laboratory experiments.",
            Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM",
            InstructorName = "Dr. Robert Kim",
            InstructorBio = "Dr. Kim is an experimental physicist whose research in optics has been funded by the NSF. He is passionate about hands-on physics education.",
            DepartmentCode = "PHYS", IsFeatured = false
        },
        new()
        {
            Id = 9, Code = "PHYS 310", Title = "Quantum Mechanics",
            Description = "Introduction to quantum theory including wave functions, the Schrödinger equation, and applications to atomic and molecular systems.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM",
            InstructorName = "Prof. Elena Volkov",
            InstructorBio = "Prof. Volkov is a theoretical physicist with groundbreaking contributions to quantum information theory and quantum computing foundations.",
            DepartmentCode = "PHYS", IsFeatured = true
        },
        new()
        {
            Id = 10, Code = "HIST 150", Title = "World History to 1500",
            Description = "Survey of major civilizations and global connections from antiquity through the medieval period.",
            Credits = 3, Schedule = "Mon/Wed 3:00–4:20 PM",
            InstructorName = "Dr. Thomas Abara",
            InstructorBio = "Dr. Abara is a historian of the ancient world with expertise in cross-cultural exchange along the Silk Road and Indian Ocean trade networks.",
            DepartmentCode = "HIST", IsFeatured = false
        },
        new()
        {
            Id = 11, Code = "HIST 320", Title = "Modern Global History",
            Description = "Examination of major political, social, and economic transformations from the Enlightenment to the present day.",
            Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM",
            InstructorName = "Prof. Katherine Liu",
            InstructorBio = "Prof. Liu is a scholar of modern East Asian history and international relations, with a focus on diplomacy and cultural exchange.",
            DepartmentCode = "HIST", IsFeatured = false
        },
    ];

    public IReadOnlyList<Department> GetDepartments() => Departments;

    public IReadOnlyList<Course> GetCourses(string? searchTerm = null, string? departmentCode = null)
    {
        IEnumerable<Course> results = Courses;

        if (!string.IsNullOrWhiteSpace(departmentCode))
        {
            results = results.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            results = results.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return results.ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() => Courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourseById(int id) => Courses.FirstOrDefault(c => c.Id == id);
}

